-- GlowIDE D1 migration 0001 — initial schema (double-entry ledger, immutable entries)
-- Apply: wrangler d1 execute glowide_db --local --file=migrations/0001_init.sql
--        wrangler d1 execute glowide_db --remote --file=migrations/0001_init.sql
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, account_type TEXT NOT NULL CHECK(account_type IN ('personal','business')), role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin','support','finance','compliance')), email_verified INTEGER NOT NULL DEFAULT 0, two_factor_enabled INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','closed')), created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS user_profiles (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, full_name TEXT, display_name TEXT, phone TEXT, country TEXT, avatar_url TEXT, preferences_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS user_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, device TEXT, ip_address TEXT, expires_at TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_sessions_user ON user_sessions(user_id);
CREATE TABLE IF NOT EXISTS roles (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT);
CREATE TABLE IF NOT EXISTS permissions (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT);
CREATE TABLE IF NOT EXISTS businesses (id TEXT PRIMARY KEY, owner_user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, registration_number TEXT, country TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','suspended')), created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS business_members (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL DEFAULT 'member', UNIQUE(business_id, user_id));
CREATE TABLE IF NOT EXISTS supported_networks (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, chain_id INTEGER, rpc_url TEXT NOT NULL, explorer_url TEXT, symbol TEXT NOT NULL, is_primary INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'testnet' CHECK(status IN ('testnet','testnet-ready','mainnet','disabled')), created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS supported_assets (id TEXT PRIMARY KEY, symbol TEXT NOT NULL, name TEXT NOT NULL, network_id TEXT NOT NULL REFERENCES supported_networks(id), contract_address TEXT, decimals INTEGER NOT NULL DEFAULT 6, UNIQUE(symbol, network_id));
CREATE TABLE IF NOT EXISTS user_wallets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, network_id TEXT NOT NULL REFERENCES supported_networks(id), address TEXT NOT NULL, wallet_type TEXT NOT NULL CHECK(wallet_type IN ('non_custodial','partner_custody','embedded')), label TEXT, UNIQUE(user_id, network_id, address));
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, owner_type TEXT NOT NULL CHECK(owner_type IN ('user','business')), owner_id TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'USD', account_type TEXT NOT NULL DEFAULT 'wallet', created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS ledger_transactions (id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, account_id TEXT NOT NULL REFERENCES accounts(id), type TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents > 0), currency TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','failed','refunded')), mode TEXT NOT NULL DEFAULT 'SIMULATED' CHECK(mode IN ('SIMULATED','TESTNET','PRODUCTION')), network_id TEXT REFERENCES supported_networks(id), external_ref TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_ledger_account ON ledger_transactions(account_id);
CREATE TABLE IF NOT EXISTS ledger_entries (id TEXT PRIMARY KEY, ledger_transaction_id TEXT NOT NULL REFERENCES ledger_transactions(id), account_id TEXT NOT NULL REFERENCES accounts(id), direction TEXT NOT NULL CHECK(direction IN ('debit','credit')), amount_cents INTEGER NOT NULL CHECK(amount_cents > 0), created_at TEXT NOT NULL DEFAULT (datetime('now')));
-- Immutable: no UPDATE/DELETE on ledger_entries in application code; enforce by trigger in production DBs that support it.
CREATE INDEX IF NOT EXISTS idx_entries_tx ON ledger_entries(ledger_transaction_id);
CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY, ledger_transaction_id TEXT REFERENCES ledger_transactions(id), from_account_id TEXT NOT NULL REFERENCES accounts(id), to_account_id TEXT NOT NULL REFERENCES accounts(id), amount_cents INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS payment_requests (id TEXT PRIMARY KEY, requester_user_id TEXT NOT NULL REFERENCES users(id), payer_ref TEXT NOT NULL, amount_cents INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'USD', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','cancelled','expired')), created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS payment_links (id TEXT PRIMARY KEY, owner_user_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, amount_cents INTEGER NOT NULL, asset_symbol TEXT NOT NULL DEFAULT 'USDC', slug TEXT NOT NULL UNIQUE, active INTEGER NOT NULL DEFAULT 1, clicks INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, name TEXT NOT NULL, email TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), customer_id TEXT REFERENCES customers(id), number TEXT NOT NULL UNIQUE, amount_cents INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'USD', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','paid','overdue','cancelled')), due_date TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS invoice_items (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, description TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1, unit_amount_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS external_integrations (id TEXT PRIMARY KEY, provider TEXT NOT NULL UNIQUE, endpoint_url TEXT, enabled INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'not_configured', last_success_at TEXT, last_error TEXT, updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS encrypted_credentials (id TEXT PRIMARY KEY, integration_id TEXT NOT NULL REFERENCES external_integrations(id) ON DELETE CASCADE, key_name TEXT NOT NULL, encrypted_value TEXT NOT NULL, -- AES-GCM ciphertext only. Master key lives in Worker secrets (ENCRYPTION_KEY), NEVER in this DB.
  created_at TEXT NOT NULL DEFAULT (datetime('now')), rotated_at TEXT);
CREATE TABLE IF NOT EXISTS ai_models (id TEXT PRIMARY KEY, model_id TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, provider TEXT NOT NULL DEFAULT 'OpenRouter', enabled INTEGER NOT NULL DEFAULT 0, is_default INTEGER NOT NULL DEFAULT 0, is_fallback INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS ai_usage (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), model_id TEXT REFERENCES ai_models(id), tokens INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'ok', error TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_ai_usage_user ON ai_usage(user_id);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, body TEXT NOT NULL, read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS verification_records (id TEXT PRIMARY KEY, subject_type TEXT NOT NULL CHECK(subject_type IN ('user','business')), subject_id TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), reviewer_id TEXT REFERENCES users(id), reason TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS support_tickets (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','resolved','closed')), created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, entity_type TEXT, entity_id TEXT, details_json TEXT, ip_address TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
-- NOTE: audit_logs.details_json must NEVER contain secret values.
CREATE INDEX IF NOT EXISTS idx_audit_actor ON audit_logs(actor_id);
CREATE TABLE IF NOT EXISTS system_settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT (datetime('now')));
